<?php $e=(bool)$invoice;$v=fn($k,$d='')=>old($k,$invoice[$k]??($_GET[$k]??$d)); ?>
<div class="form-card"><form method="post" enctype="multipart/form-data" action="<?= $e?url('/invoices/'.$invoice['id']):url('/invoices') ?>"><?= csrf_field() ?><?php if($e)echo method_field('PUT');?><div class="section-title"><i class="bi bi-receipt"></i><div x-data="{ showInfo: false }"><div class="d-inline-flex align-items-center gap-2"><h3 class="m-0">Informasi Invoice</h3><button type="button" @click="showInfo = !showInfo" class="info-toggle-btn" :class="{ 'is-active': showInfo }" :aria-expanded="showInfo.toString()" aria-label="Tampilkan info invoice" title="Informasi bantuan"><i class="bi bi-info-circle text-xs leading-none"></i></button></div><p x-show="showInfo" x-cloak x-transition style="display: none;">Kelola invoice dan keterkaitannya dengan transaksi.</p></div></div><div class="row g-3"><div class="col-md-4"><label class="form-label">Nomor Invoice *</label><input class="form-control" name="invoice_no" value="<?= e($v('invoice_no')) ?>" required></div><div class="col-md-4"><label class="form-label">Perusahaan *</label><select class="form-select" name="company_id" required><option value="">Pilih perusahaan</option><?php foreach($companies as$c):?><option value="<?= $c['id'] ?>" <?= selected($v('company_id'),$c['id']) ?>><?= e($c['name']) ?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Transaksi Terkait</label><select class="form-select" name="transaction_id"><option value="">Tidak ada</option><?php foreach($transactions as$t):?><option value="<?= $t['id'] ?>" <?= selected($v('transaction_id'),$t['id']) ?>><?= e(($t['reference_no']?:'TRX-'.$t['id']).' · '.$t['company_name']) ?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Issue Date</label><input type="date" class="form-control" name="issue_date" value="<?= e($v('issue_date',date('Y-m-d'))) ?>"></div><div class="col-md-3"><label class="form-label">Due Date</label><input type="date" class="form-control" name="due_date" value="<?= e($v('due_date')) ?>"></div><div class="col-md-3"><label class="form-label">Nominal</label><input type="number" step="0.01" class="form-control" name="amount" value="<?= e($v('amount',0)) ?>"></div><div class="col-md-3"><label class="form-label">Mata Uang</label><input class="form-control" name="currency" maxlength="3" value="<?= e($v('currency','USD')) ?>"></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['draft','sent','paid','overdue','cancelled']as$s):?><option value="<?= $s ?>" <?= selected($v('status','draft'),$s) ?>><?= strtoupper($s) ?></option><?php endforeach;?></select></div><div class="col-md-8"><label class="form-label">Lampiran</label><input type="file" class="form-control" name="attachment"></div><div class="col-12"><label class="form-label">Catatan</label><textarea class="form-control" rows="3" name="notes"><?= e($v('notes')) ?></textarea></div></div><div class="form-actions"><a class="btn btn-light" href="<?= url('/invoices') ?>">Batal</a><button class="btn btn-primary">Simpan</button></div></form></div>
